72	    /**
73	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
74	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
75	     * and a dotted domain (e.g. {@code not-an-email}).
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
78	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
79	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
80	
81	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
82	    private static final String DEFAULT_COUNTRY_CODE = "61";
83	
84	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
85	    private static final int MAX_OWNERS_PER_CITY = 50;
86	
87	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
88	    private static final int MAX_OWNERS_PER_DAY = 100;
89	
90	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
91	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
92	
93	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
94	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
95	
96	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
97	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
98	
99	    /**
100	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
101	     * is listed here must carry exactly the required number of national digits, otherwise it is
102	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
103	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
104	     */
105	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
106	        "61", 9,
107	        "1", 10);
108	
109	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
110	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
111	        "ST", "STREET",
112	        "RD", "ROAD",
113	        "AVE", "AVENUE");
114	
115	    /** A well-formed postcode: exactly four digits. */
116	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
117	
118	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
119	    private static final Map<String, String> CITY_REGION = Map.of(
120	        "Sydney", "NSW",
121	        "Melbourne", "VIC",
122	        "Brisbane", "QLD");
123	
124	    /** Region to its inclusive 4-digit postcode range {low, high}. */
125	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
126	        "NSW", new int[] {2000, 2099},
127	        "VIC", new int[] {3000, 3099},
128	        "QLD", new int[] {4000, 4099});
129	
130	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
131	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
132	
