178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
181	        List<String> missingFields = new ArrayList<>();
182	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
183	            missingFields.add("firstName");
184	        }
185	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
186	            missingFields.add("lastName");
187	        }
188	        // Normalize the address up front; the required-field check rejects it when it is blank
189	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
190	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
191	        if (!StringUtils.hasText(normalizedAddress)) {
192	            missingFields.add("address");
193	        }
194	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
195	            missingFields.add("city");
196	        }
197	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
198	            missingFields.add("telephone");
199	        }
200	        if (!missingFields.isEmpty()) {
201	            throw new InvalidRequestException(missingFields);
202	        }
203	        HttpHeaders headers = new HttpHeaders();
204	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
205	        // Store (and later return) the normalized address computed above.
206	        owner.setAddress(normalizedAddress);
207	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
208	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
209	        owner.setTelephone(normalizedTelephone);
210	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
211	        owner.setEmail(normalizeEmail(owner.getEmail()));
212	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
213	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
214	        validatePostcode(owner.getCity(), owner.getPostcode());
215	        // Reject a supplied registration date that lies in the future (later than the server's current
216	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
217	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
218	            throw new InvalidRequestException(List.of("registrationDate"));
219	        }
220	        // Default the (optional) registration date to the server's current date when none was supplied.
221	        if (owner.getRegistrationDate() == null) {
222	            owner.setRegistrationDate(LocalDate.now());
223	        }
224	        // The effective registration date must fall on a business day: when it lands on a Saturday or
225	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
226	        // derived from the registration date below (daily create-limit, membership number) uses this
227	        // adjusted date.
228	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
229	        // Reject the request once the maximum number of owners for the owner's registration day has
230	        // been reached (100 or more owners already created on that date).
231	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
232	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
233	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
234	        }
235	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
236	        // owner's registration day at the moment this owner was created; otherwise clear it.
237	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
238	        // Reject the request when the owner's city has already reached its owner capacity.
239	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
240	            throw new CityCapacityException(owner.getCity());
241	        }
242	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
243	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
244	        // so any two owners with the same last name and postcode automatically resolve to the same
245	        // household without an explicit opt-in. It is assigned up front so it feeds duplicate
246	        // detection (the identity key below), the household-size read-back and household-duplicate
247	        // detection alike.
248	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
249	        owner.setHouseholdId(householdId);
250	        // Household-duplicate detection: because the household is keyed on (lastName, postcode), any
251	        // existing owner already carrying this householdId is a member of the same household, so this
252	        // create is a household duplicate. Reject it with 409 unless the caller opts in via
253	        // 'sharesHousehold', which now only bypasses this block (the household link already exists by
254	        // construction) and marks the owner as a declared household member.
255	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
256	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
257	        boolean declaredHouseholdMember = false;
258	        if (householdMemberExists) {
259	            if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
260	                declaredHouseholdMember = true;
261	            } else {
262	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
263	            }
264	        }
265	        // All duplicate detection is consolidated into this single derived identity key
266	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
267	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
268	        // telephone is part of the key, two members of the same household with different telephones
269	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
270	        String identityKey = owner.getIdentityKey();
271	        boolean identityCollision = this.clinicService.findAllOwners().stream()
272	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
273	        if (identityCollision) {
274	            throw new DuplicateIdentityException(identityKey);
275	        }
276	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
277	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
278	        // this owner's last name (compared case-insensitively with collapsed whitespace) and
279	        // postcode while carrying a DIFFERENT normalized telephone. When several existing owners
280	        // match, the one with the lowest id is chosen so the result is deterministic. A declared
281	        // household member is an intentional co-resident, not a suspected duplicate, so it is never
282	        // flagged (a create that reaches this point sharing a last name and postcode with an
283	        // existing owner is precisely a declared household member).
284	        Owner softMatch = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
285	        if (softMatch != null) {
286	            owner.setPossibleDuplicate(true);
287	            owner.setPossibleDuplicateOf(softMatch.getId());
288	        } else {
289	            owner.setPossibleDuplicate(false);
290	        }
291	        // Record how many existing owners already share this first name and last name
292	        // (compared case-insensitively) before this owner is created.
293	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
294	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
295	        owner.setCustomerCode(generateCustomerCode(owner));
296	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
297	        // digits of the registration date year (e.g. 'NSW-1A2B3C4D-M26').
298	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
299	        this.clinicService.saveOwner(owner);
300	        populateHouseholdSize(owner);
301	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
302	        // Emit an audit line carrying the new owner's id, customer code, registration date
303	        // and numeric membership level.
304	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
305	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
306	            ownerDto.getMembershipLevel());
307	        headers.setLocation(UriComponentsBuilder.newInstance()
308	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
309	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
310	    }
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
315	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
316	        if (currentOwner == null) {
317	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
