327	    }
328	
329	    /**
330	     * Populate the owner's household size: the number of owners sharing this owner's
331	     * {@code householdId} (including the owner itself). An owner with no household is a household
332	     * of one.
333	     *
334	     * @param owner the owner whose household size should be computed and set
335	     */
336	    private void populateHouseholdSize(Owner owner) {
337	        String householdId = owner.getHouseholdId();
338	        if (!StringUtils.hasText(householdId)) {
339	            owner.setHouseholdSize(1);
340	            return;
341	        }
342	        int size = (int) this.clinicService.findAllOwners().stream()
343	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
344	            .count();
345	        owner.setHouseholdSize(size);
346	    }
347	
348	    /**
349	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
350	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
351	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
352	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
353	     * longer any per-city sequence number.
354	     *
355	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
356	     * @return the generated customer code
357	     */
358	    private String generateCustomerCode(Owner owner) {
359	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
360	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
361	        return region + "-" + hash8;
362	    }
363	
364	    /**
365	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
366	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
367	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
368	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
369	     * known region.
370	     *
371	     * @param postcode the owner's postcode, may be {@code null}
372	     * @param city     the owner's city
373	     * @return the derived region code
374	     */
375	    private String deriveRegion(String postcode, String city) {
376	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
377	            int value = Integer.parseInt(postcode);
378	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
379	                int[] range = entry.getValue();
380	                if (value >= range[0] && value <= range[1]) {
381	                    return entry.getKey();
382	                }
383	            }
384	        }
385	        String region = CITY_REGION.get(city);
386	        return region != null ? region : "UNKNOWN";
387	    }
388	
389	    /**
390	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
391	     * bytes of {@code input}.
392	     *
393	     * @param input  the value to digest
394	     * @param length the number of leading hex characters to return
395	     * @return the truncated upper-case hex digest
396	     */
397	    private String shortSha256Hex(String input, int length) {
398	        try {
399	            byte[] digest = MessageDigest.getInstance("SHA-256")
400	                .digest(input.getBytes(StandardCharsets.UTF_8));
401	            StringBuilder sb = new StringBuilder(digest.length * 2);
402	            for (byte b : digest) {
403	                sb.append(String.format("%02x", b));
404	            }
405	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
406	        } catch (java.security.NoSuchAlgorithmException e) {
407	            throw new IllegalStateException("SHA-256 not available", e);
408	        }
409	    }
410	
411	    /**
412	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
413	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
414	     * that is stored, returned and used for every value derived from it.
415	     *
416	     * @param date the effective registration date (supplied or defaulted)
417	     * @return the same date when it is a weekday, otherwise the next Monday
418	     */
419	    private LocalDate rollToBusinessDay(LocalDate date) {
420	        DayOfWeek dayOfWeek = date.getDayOfWeek();
421	        if (dayOfWeek == DayOfWeek.SATURDAY) {
422	            return date.plusDays(2);
423	        }
424	        if (dayOfWeek == DayOfWeek.SUNDAY) {
425	            return date.plusDays(1);
426	        }
427	        return date;
428	    }
429	
430	    /**
431	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
432	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
433	     *
434	     * @param customerCode     the owner's already-assigned customer code
435	     * @param registrationDate the owner's registration date
436	     * @return the generated membership number
437	     */
438	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
439	        String yy = String.format("%02d", registrationDate.getYear() % 100);
440	        return String.format("%s-M%s", customerCode, yy);
441	    }
442	
443	    /**
444	     * Count the existing owners that share the given first name and last name, comparing each
445	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
446	     * yet persisted, so it is not included in the count.
447	     *
448	     * @param firstName the incoming owner's first name
449	     * @param lastName  the incoming owner's last name
450	     * @return the number of existing namesakes
451	     */
452	    private int countNamesakes(String firstName, String lastName) {
453	        String normalizedFirstName = normalizeForComparison(firstName);
454	        String normalizedLastName = normalizeForComparison(lastName);
455	        return (int) this.clinicService.findAllOwners().stream()
456	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
457	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
458	            .count();
459	    }
460	
461	    /**
462	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
463	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
464	     *
465	     * @param city the incoming owner's city
466	     * @return the number of existing owners already in that city
467	     */
468	    private int countOwnersInCity(String city) {
469	        String normalizedCity = normalizeForComparison(city);
470	        return (int) this.clinicService.findAllOwners().stream()
471	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
472	            .count();
473	    }
474	
475	    /**
476	     * Count the existing owners whose registration date equals the given date. The incoming owner is
477	     * not yet persisted, so it is not included in the count.
478	     *
479	     * @param registrationDate the incoming owner's registration date
480	     * @return the number of existing owners already registered on that date
481	     */
482	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
483	        return (int) this.clinicService.findAllOwners().stream()
484	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
485	            .count();
486	    }
487	
488	    /**
489	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
490	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
491	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
492	     * (postcode is required for the match). When several owners match, the one with the lowest id is
493	     * returned so the result is deterministic; {@code null} when there is no soft match.
494	     *
495	     * @param owner the incoming owner (with normalized telephone and last name resolved)
496	     * @return the lowest-id matching existing owner, or {@code null} when none matches
497	     */
498	    private Owner findPossibleDuplicate(Owner owner) {
499	        if (!StringUtils.hasText(owner.getPostcode())) {
500	            return null;
501	        }
502	        String normalizedLastName = normalizeForComparison(owner.getLastName());
503	        String telephone = owner.getTelephone();
504	        return this.clinicService.findAllOwners().stream()
505	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
506	                && owner.getPostcode().equals(existing.getPostcode())
507	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
508	            .min(java.util.Comparator.comparing(Owner::getId))
509	            .orElse(null);
510	    }
511	
512	    /**
513	     * Generate the deterministic household identifier for the given last name and postcode. The value
514	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
515	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
516	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
517	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
518	     *
519	     * @param lastName the owner's last name
520	     * @param postcode the owner's postcode, may be {@code null}
521	     * @return the deterministic household identifier
522	     */
523	    private String generateHouseholdId(String lastName, String postcode) {
524	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
525	        return shortSha256Hex(key, 12);
526	    }
527	
528	    /**
529	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
530	     * single space, upper-case the result and expand common street-type abbreviations token by token
531	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
532	     * to the empty string. The result is the canonical form that is stored, returned and used for every
533	     * address comparison (household duplicate detection and the shared household id).
534	     *
535	     * @param address the raw address, may be {@code null}
536	     * @return the normalized address
537	     */
538	    private String normalizeAddress(String address) {
539	        if (address == null) {
540	            return "";
541	        }
542	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
543	        if (collapsed.isEmpty()) {
544	            return "";
545	        }
546	        String[] tokens = collapsed.split(" ");
547	        StringBuilder sb = new StringBuilder(collapsed.length());
548	        for (int i = 0; i < tokens.length; i++) {
549	            if (i > 0) {
550	                sb.append(' ');
551	            }
552	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
553	        }
554	        return sb.toString();
555	    }
556	
557	    /**
558	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
559	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
560	     *
561	     * @param value the raw value, may be {@code null}
562	     * @return the normalized value
563	     */
564	    private String normalizeForComparison(String value) {
565	        if (value == null) {
566	            return "";
567	        }
568	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
569	    }
570	
571	    /**
572	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
573	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
574	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
575	     * is returned lower-cased.
576	     *
577	     * @param email the raw email from the request payload, may be {@code null}
578	     * @return the lower-cased email, or {@code null} when none was provided
579	     */
580	    private String normalizeEmail(String email) {
581	        if (!StringUtils.hasText(email)) {
582	            return null;
583	        }
584	        if (!EMAIL_PATTERN.matcher(email).matches()) {
585	            throw new InvalidRequestException(List.of("email"));
586	        }
587	        return email.toLowerCase(Locale.ROOT);
588	    }
589	
590	    /**
591	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
592	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
593	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
594	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
595	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
596	     * to 400 Bad Request).
597	     *
598	     * @param city     the owner's city (used to resolve the region)
599	     * @param postcode the raw postcode from the request payload, may be {@code null}
600	     */
601	    private void validatePostcode(String city, String postcode) {
602	        if (!StringUtils.hasText(postcode)) {
603	            return;
604	        }
605	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
606	            throw new InvalidRequestException(List.of("postcode"));
607	        }
608	        String region = CITY_REGION.get(city);
609	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
610	        if (range != null) {
611	            int value = Integer.parseInt(postcode);
612	            if (value < range[0] || value > range[1]) {
613	                throw new InvalidRequestException(List.of("postcode"));
614	            }
615	        }
616	    }
617	
618	    /**
619	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
620	     * already carries a leading '+' keeps its country code; otherwise the default country code
621	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
622	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
623	     * is thrown (mapped to 400 Bad Request).
624	     *
625	     * @param telephone the raw telephone from the request payload
626	     * @return the E.164 string (e.g. {@code +61412345678})
627	     */
628	    private String normalizeTelephone(String telephone) {
629	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
630	        String candidate;
631	        if (cleaned.startsWith("+")) {
632	            candidate = cleaned;
633	        } else {
634	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
635	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
636	        }
637	        if (!E164_PATTERN.matcher(candidate).matches()) {
638	            throw new InvalidRequestException(List.of("telephone"));
639	        }
640	        // For country codes with a known fixed national-number length, reject a candidate whose
641	        // national digits (everything after the '+' and the country code) do not match that length.
642	        String digits = candidate.substring(1);
643	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
644	            String countryCode = entry.getKey();
645	            if (digits.startsWith(countryCode)) {
646	                int nationalLength = digits.length() - countryCode.length();
647	                if (nationalLength != entry.getValue()) {
648	                    throw new InvalidRequestException(List.of("telephone"));
649	                }
650	                break;
651	            }
652	        }
653	        return candidate;
654	    }
655	
656	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
657	    @Transactional
658	    @Override
659	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
660	        Owner owner = this.clinicService.findOwnerById(ownerId);
661	        if (owner == null) {
662	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
663	        }
664	        this.clinicService.deleteOwner(owner);
665	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
666	    }
667	
668	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
669	    @Override
670	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
671	        Owner owner = this.clinicService.findOwnerById(ownerId);
672	        if (owner == null) {
673	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
674	        }
675	        HttpHeaders headers = new HttpHeaders();
676	        Pet pet = petMapper.toPet(petFieldsDto);
677	        owner.setId(ownerId);
678	        pet.setOwner(owner);
679	        pet.getType().setName(null);
680	        this.clinicService.savePet(pet);
681	        PetDto petDto = petMapper.toPetDto(pet);
682	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
683	            .buildAndExpand(pet.getId()).toUri());
684	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
685	    }
686	
687	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
688	    @Override
689	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
690	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
691	        if (currentOwner != null) {
692	            Pet currentPet = this.clinicService.findPetById(petId);
693	            if (currentPet != null) {
694	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
695	                currentPet.setName(petFieldsDto.getName());
696	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
697	                this.clinicService.savePet(currentPet);
698	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
699	            }
700	        }
701	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
702	    }
703	
704	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
705	    @Override
706	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
707	        HttpHeaders headers = new HttpHeaders();
708	        Visit visit = visitMapper.toVisit(visitFieldsDto);
709	        Pet pet = new Pet();
710	        pet.setId(petId);
711	        visit.setPet(pet);
712	        this.clinicService.saveVisit(visit);
713	        VisitDto visitDto = visitMapper.toVisitDto(visit);
714	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
715	            .buildAndExpand(visit.getId()).toUri());
716	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
717	    }
718	
719	
720	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
721	    @Override
722	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
723	        Owner owner = this.clinicService.findOwnerById(ownerId);
724	        if (owner != null) {
725	            Pet pet = owner.getPet(petId);
726	            if (pet != null) {
727	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
728	            }
729	        }
730	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
731	    }
732	}
